record.field:
website = env.ref('toy_store.website_industry')
to_deactivate = [ # Presets 'website_sale.carousel_product_indicators_left', 'website_sale.header_hide_empty_wishlist_link', 'website_sale.product_attributes_body', 'website_sale.products_attributes', 'website.footer_custom', 'website.header_call_to_action', 'website.header_search_box', 'website.header_text_element', 'website.header_visibility_standard', 'website.template_header_default', 'website.template_footer_links', # Default static pages 'website.homepage', 'website.contactus', ] to_activate = [ # Presets 'website_sale.accept_terms_and_conditions', 'website_sale.accordion_specs_item', 'website_sale.carousel_product_indicators_bottom', 'website_sale.checkout_container_dropzone', 'website_sale.cta_wrapper_boxed', 'website_sale.filmstrip_categories_bordered', 'website_sale.filter_products_price', 'website_sale.product_comment', 'website_sale.product_search', 'website_sale.products_attributes_top', 'website.footer_no_copyright', 'website.header_visibility_fixed', 'website.template_header_additional_color_primary', 'website.template_header_mobile_position_left', 'website.template_header_sales_one', 'website.template_header_sales_one_align_center', 'portal.user_sign_in', 'website.template_footer_call_to_action', 'website_event.opt_event_description_cover_top', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
# Set up the main menu, reusing the menus the dependencies already provide # (website_sale: /shop, website_event: /event) rather than duplicating them menus = env['website.menu'] base_domain = [('website_id', '=', website.id)] menus.search(base_domain + [('url', 'in', ['/', '/appointment'])]).unlink() top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1)
for name, url, sequence in [ ('Catalog', '/shop', 10), ('The store', '/about-us', 20), ('Board game nights', '/event', 30), ('Contact', '/contactus', 40), ]: vals = {'name': name, 'sequence': sequence} menu = menus.search(base_domain + [('url', '=', url), ('parent_id', '=', top_menu.id)], limit=1) if menu: menu.write(vals) else: menus.create(dict(vals, url=url, website_id=website.id, parent_id=top_menu.id))
